//! Parity tests for `nltk.tokenize.casual` against fixtures generated by
//! `parity/gen_fixtures.py`.

mod common;

use std::collections::HashMap;

use nltk::tokenize::casual::{
  self, EMOTICONS, ENT_RE_SRC, FLAGS, Flags, HANDLES_RE_SRC, HANG_RE_SRC, PHONE_REGEX, REGEXPS,
  REGEXPS_PHONE, TweetTokenizer, URLS, VERBOSE_I,
};
use serde::Deserialize;

use common::{all_chars, read_json, read_jsonl};

/// Inputs whose tokens differ from Python. See parity/README.md.
const TOKENIZE_EXCEPTIONS: &[&str] = &[];

/// Character-class probes whose code point sets differ from Python, with the
/// code points that differ. See parity/README.md.
const CLASS_EXCEPTIONS: &[(&str, bool, &[u32])] = &[];

#[derive(Deserialize)]
struct Sources {
  #[serde(rename = "EMOTICONS")]
  emoticons: String,
  #[serde(rename = "URLS")]
  urls: String,
  #[serde(rename = "FLAGS")]
  flags_re: String,
  #[serde(rename = "PHONE_REGEX")]
  phone_regex: String,
  #[serde(rename = "REGEXPS")]
  regexps: Vec<String>,
  #[serde(rename = "REGEXPS_PHONE")]
  regexps_phone: Vec<String>,
  #[serde(rename = "WORD_RE")]
  word_re: (String, u32),
  #[serde(rename = "PHONE_WORD_RE")]
  phone_word_re: (String, u32),
  #[serde(rename = "HANG_RE")]
  hang_re: (String, u32),
  #[serde(rename = "EMOTICON_RE")]
  emoticon_re: (String, u32),
  #[serde(rename = "ENT_RE")]
  ent_re: (String, u32),
  #[serde(rename = "HANDLES_RE")]
  handles_re: (String, u32),
  flags: HashMap<String, u32>,
  atoms: HashMap<String, Vec<String>>,
}

#[test]
fn atom_scanner_matches_python() {
  let s: Sources = read_json("regex_sources.json");
  let word_re = format!("({})", REGEXPS.join("|"));
  let phone_word_re = format!("({})", REGEXPS_PHONE.join("|"));
  let patterns: [(&str, &str, bool); 7] = [
    ("WORD_RE", &word_re, true),
    ("PHONE_WORD_RE", &phone_word_re, true),
    ("EMOTICON_RE", EMOTICONS, true),
    ("HANG_RE", HANG_RE_SRC, false),
    ("ENT_RE", ENT_RE_SRC, false),
    ("HANDLES_RE", HANDLES_RE_SRC, false),
    ("reduce_lengthening", r"(.)\1{2,}", false),
  ];
  assert_eq!(s.atoms.len(), patterns.len());
  for (name, src, vi) in patterns {
    let src = if vi {
      casual::strip_verbose(src)
    } else {
      src.to_owned()
    };
    assert_eq!(casual::atoms(&src, vi), s.atoms[name], "{name}");
  }
}

#[test]
fn regex_sources_are_identical() {
  let s: Sources = read_json("regex_sources.json");
  assert_eq!(s.emoticons, EMOTICONS);
  assert_eq!(s.urls, URLS);
  assert_eq!(s.flags_re, FLAGS);
  assert_eq!(s.phone_regex, PHONE_REGEX);
  assert_eq!(s.regexps, REGEXPS);
  assert_eq!(s.regexps_phone, REGEXPS_PHONE);
  assert_eq!(s.word_re.0, format!("({})", REGEXPS.join("|")));
  assert_eq!(s.phone_word_re.0, format!("({})", REGEXPS_PHONE.join("|")));
  assert_eq!(s.hang_re.0, HANG_RE_SRC);
  assert_eq!(s.emoticon_re.0, EMOTICONS);
  assert_eq!(s.ent_re.0, ENT_RE_SRC);
  assert_eq!(s.handles_re.0, HANDLES_RE_SRC);

  // Flags: VERBOSE | I for the tokenizer and emoticon regexes, neither for
  // the others. UNICODE is the default for str patterns.
  let verbose = s.flags["VERBOSE"];
  let ignorecase = s.flags["I"];
  let vi = verbose | ignorecase;
  assert_eq!((VERBOSE_I.verbose, VERBOSE_I.ignorecase), (true, true));
  for (name, flags) in [
    ("WORD_RE", s.word_re.1),
    ("PHONE_WORD_RE", s.phone_word_re.1),
    ("EMOTICON_RE", s.emoticon_re.1),
  ] {
    assert_eq!(flags & vi, vi, "{name}");
  }
  for (name, flags) in [
    ("HANG_RE", s.hang_re.1),
    ("ENT_RE", s.ent_re.1),
    ("HANDLES_RE", s.handles_re.1),
  ] {
    assert_eq!(flags & vi, 0, "{name}");
  }
}

#[derive(Deserialize)]
struct ClassProbe {
  pattern: String,
  verbose_ignorecase: bool,
  prefix: String,
  ranges: Vec<(u32, u32)>,
}

#[test]
fn character_classes_match_python() {
  let probes: Vec<ClassProbe> = read_json("char_classes.json");
  let all: String = all_chars().collect();
  let run = |p: &ClassProbe| -> Option<(String, bool, Vec<u32>)> {
    let flags = Flags {
      verbose: p.verbose_ignorecase,
      ignorecase: p.verbose_ignorecase,
    };
    let mut got = vec![false; 0x110000];
    let re = casual::compile(&p.pattern, flags);
    if p.prefix.is_empty() {
      for m in re.find_iter(&all) {
        let m = m.unwrap();
        let mut cs = m.as_str().chars();
        let c = cs.next().unwrap();
        assert!(
          cs.next().is_none(),
          "{} matched {:?}",
          p.pattern,
          m.as_str()
        );
        got[c as usize] = true;
      }
    } else {
      // `prefix + c` for every c, concatenated. The probes only look at the
      // prefix and the character right after it.
      let mut s = String::new();
      let mut starts = std::collections::HashMap::new();
      for c in all_chars() {
        starts.insert(s.len(), c);
        s.push_str(&p.prefix);
        s.push(c);
      }
      for m in re.find_iter(&s) {
        let m = m.unwrap();
        let c = starts[&m.start()];
        assert_eq!(m.as_str(), p.prefix, "{}", p.pattern);
        got[c as usize] = true;
      }
    }
    let mut expected = vec![false; 0x110000];
    for &(lo, hi) in &p.ranges {
      for c in lo..=hi {
        expected[c as usize] = true;
      }
    }
    let differing: Vec<u32> = all_chars()
      .map(|c| c as u32)
      .filter(|&c| got[c as usize] != expected[c as usize])
      .collect();
    (!differing.is_empty()).then(|| (p.pattern.clone(), p.verbose_ignorecase, differing))
  };
  let diffs: Vec<(String, bool, Vec<u32>)> = std::thread::scope(|scope| {
    let handles: Vec<_> = probes
      .chunks(probes.len().div_ceil(8))
      .map(|chunk| scope.spawn(move || chunk.iter().filter_map(run).collect::<Vec<_>>()))
      .collect();
    handles
      .into_iter()
      .flat_map(|h| h.join().unwrap())
      .collect()
  });
  for (pat, vi, cps) in &diffs {
    let shown: Vec<String> = cps.iter().take(40).map(|c| format!("{c:#06x}")).collect();
    eprintln!("{pat:?} vi={vi}: {} differ: {}", cps.len(), shown.join(" "));
  }
  let expected: Vec<(String, bool, Vec<u32>)> = CLASS_EXCEPTIONS
    .iter()
    .map(|(p, vi, cps)| ((*p).to_owned(), *vi, cps.to_vec()))
    .collect();
  assert_eq!(diffs, expected);
  eprintln!(
    "char_classes.json: {} probes over every code point, all exact",
    probes.len()
  );
}

#[derive(Deserialize)]
struct TokenizeRecord {
  text: String,
  tokens: Vec<String>,
  #[serde(default)]
  surrogate: bool,
}

/// A surrogate record must contain an entity that Python decodes to a lone
/// surrogate, which the port turns into U+FFFD.
fn check_surrogate_record(text: &str) {
  let replaced = casual::_replace_html_entities(text, &[], true).unwrap();
  assert!(
    replaced.matches('\u{FFFD}').count() > text.matches('\u{FFFD}').count(),
    "record flagged as surrogate has no surrogate entity: {text:?}"
  );
}

fn check_tokenize(name: &str, records: &[(TweetTokenizer, TokenizeRecord)]) -> (usize, usize) {
  let mut mismatches = Vec::new();
  let mut surrogates = 0;
  for (tk, r) in records {
    if r.surrogate {
      check_surrogate_record(&r.text);
      surrogates += 1;
    }
    let got = tk.tokenize(&r.text).unwrap();
    if got != r.tokens {
      if mismatches.len() < 20 {
        eprintln!(
          "{name}: {tk:?}\n  text:   {:?}\n  python: {:?}\n  rust:   {:?}",
          r.text, r.tokens, got
        );
      }
      mismatches.push(r.text.as_str());
    }
  }
  mismatches.sort_unstable();
  mismatches.dedup();
  let mut expected = TOKENIZE_EXCEPTIONS.to_vec();
  expected.sort_unstable();
  let expected: Vec<&str> = expected
    .into_iter()
    .filter(|e| records.iter().any(|(_, r)| r.text == *e))
    .collect();
  assert_eq!(mismatches, expected, "{name}: unexpected mismatches");
  eprintln!(
    "{name}: {} cases, {} exact, {} with lone surrogates mapped to U+FFFD",
    records.len(),
    records.len() - mismatches.len(),
    surrogates
  );
  (records.len(), mismatches.len())
}

#[test]
fn tokenize_matches_python() {
  let records: Vec<TokenizeRecord> = read_jsonl("tokenize.jsonl");
  assert!(records.len() >= 5000);
  let records: Vec<_> = records
    .into_iter()
    .map(|r| (TweetTokenizer::new(), r))
    .collect();
  check_tokenize("tokenize.jsonl", &records);
}

#[test]
fn tokenize_corpus_matches_python() {
  let records: Vec<TokenizeRecord> = read_jsonl("corpus.jsonl");
  assert!(!records.is_empty());
  let records: Vec<_> = records
    .into_iter()
    .map(|r| (TweetTokenizer::new(), r))
    .collect();
  check_tokenize("corpus.jsonl", &records);
}

#[derive(Deserialize)]
struct Options {
  preserve_case: Option<bool>,
  reduce_len: Option<bool>,
  strip_handles: Option<bool>,
  match_phone_numbers: Option<bool>,
}

#[derive(Deserialize)]
struct OptionsRecord {
  opts: Options,
  #[serde(flatten)]
  record: TokenizeRecord,
}

#[test]
fn tokenize_options_match_python() {
  let records: Vec<OptionsRecord> = read_jsonl("tokenize_options.jsonl");
  let records: Vec<_> = records
    .into_iter()
    .map(|r| {
      let d = TweetTokenizer::default();
      let tk = TweetTokenizer {
        preserve_case: r.opts.preserve_case.unwrap_or(d.preserve_case),
        reduce_len: r.opts.reduce_len.unwrap_or(d.reduce_len),
        strip_handles: r.opts.strip_handles.unwrap_or(d.strip_handles),
        match_phone_numbers: r.opts.match_phone_numbers.unwrap_or(d.match_phone_numbers),
      };
      (tk, r.record)
    })
    .collect();
  check_tokenize("tokenize_options.jsonl", &records);
}

#[test]
fn docstring_examples() {
  let tknzr = TweetTokenizer::new();
  let s0 = "This is a cooool #dummysmiley: :-) :-P <3 and some arrows < > -> <--";
  assert_eq!(
    tknzr.tokenize(s0).unwrap(),
    [
      "This",
      "is",
      "a",
      "cooool",
      "#dummysmiley",
      ":",
      ":-)",
      ":-P",
      "<3",
      "and",
      "some",
      "arrows",
      "<",
      ">",
      "->",
      "<--"
    ]
  );
  let tknzr = TweetTokenizer {
    strip_handles: true,
    reduce_len: true,
    ..TweetTokenizer::default()
  };
  let s1 = "@remy: This is waaaaayyyy too much for you!!!!!!";
  assert_eq!(
    tknzr.tokenize(s1).unwrap(),
    [
      ":", "This", "is", "waaayyy", "too", "much", "for", "you", "!", "!", "!"
    ]
  );
  assert_eq!(
    casual::_replace_html_entities("Price: &pound;100", &[], true).unwrap(),
    "Price: \u{a3}100"
  );
  assert_eq!(
    casual::_replace_html_entities("&pound; &bogus;", &["pound"], false).unwrap(),
    "&pound; &bogus;"
  );
}
